     1→// type_system.dart - 타입 시스템 데이터 모델
     2→// FreeLang의 기본 타입, 제네릭, 함수 타입 정의
     3→
     4→/// 모든 FreeLang 타입의 기반 추상 클래스
     5→abstract class FreeLangType {
     6→  String get name;
     7→
     8→  /// 이 타입을 다른 타입에 할당할 수 있는지 검사
     9→  bool isAssignableTo(FreeLangType other);
    10→
    11→  @override
    12→  String toString() => name;
    13→}
    14→
    15→/// 원시 타입 (i32, string, bool 등)
    16→class PrimitiveType extends FreeLangType {
    17→  @override
    18→  final String name;
    19→
    20→  PrimitiveType(this.name);
    21→
    22→  @override
    23→  bool isAssignableTo(FreeLangType other) {
    24→    if (other is PrimitiveType) {
    25→      return name == other.name;
    26→    }
    27→    if (other is PrimitiveType && other.name == 'unknown') {
    28→      return true; // unknown 타입에는 모든 타입 할당 가능
    29→    }
    30→    return false;
    31→  }
    32→
    33→  @override
    34→  bool operator ==(Object other) =>
    35→      identical(this, other) ||
    36→      other is PrimitiveType &&
    37→          runtimeType == other.runtimeType &&
    38→          name == other.name;
    39→
    40→  @override
    41→  int get hashCode => name.hashCode;
    42→}
    43→
    44→/// 배열 타입 (Array<T>)
    45→class ArrayType extends FreeLangType {
    46→  final FreeLangType elementType;
    47→
    48→  ArrayType(this.elementType);
    49→
    50→  @override
    51→  String get name => 'array<${elementType.name}>';
    52→
    53→  @override
    54→  bool isAssignableTo(FreeLangType other) {
    55→    if (other is ArrayType) {
    56→      return elementType.isAssignableTo(other.elementType);
    57→    }
    58→    return false;
    59→  }
    60→
    61→  @override
    62→  bool operator ==(Object other) =>
    63→      identical(this, other) ||
    64→      other is ArrayType &&
    65→          runtimeType == other.runtimeType &&
    66→          elementType == other.elementType;
    67→
    68→  @override
    69→  int get hashCode => elementType.hashCode;
    70→}
    71→
    72→/// 맵 타입 (Map<K, V>)
    73→class MapType extends FreeLangType {
    74→  final FreeLangType keyType;
    75→  final FreeLangType valueType;
    76→
    77→  MapType(this.keyType, this.valueType);
    78→
    79→  @override
    80→  String get name => 'map<${keyType.name},${valueType.name}>';
    81→
    82→  @override
    83→  bool isAssignableTo(FreeLangType other) {
    84→    if (other is MapType) {
    85→      return keyType.isAssignableTo(other.keyType) &&
    86→          valueType.isAssignableTo(other.valueType);
    87→    }
    88→    return false;
    89→  }
    90→
    91→  @override
    92→  bool operator ==(Object other) =>
    93→      identical(this, other) ||
    94→      other is MapType &&
    95→          runtimeType == other.runtimeType &&
    96→          keyType == other.keyType &&
    97→          valueType == other.valueType;
    98→
    99→  @override
   100→  int get hashCode => Object.hash(keyType, valueType);
   101→}
   102→
   103→/// 옵션 타입 (Option<T>)
   104→class OptionType extends FreeLangType {
   105→  final FreeLangType innerType;
   106→
   107→  OptionType(this.innerType);
   108→
   109→  @override
   110→  String get name => 'option<${innerType.name}>';
   111→
   112→  @override
   113→  bool isAssignableTo(FreeLangType other) {
   114→    if (other is OptionType) {
   115→      return innerType.isAssignableTo(other.innerType);
   116→    }
   117→    return false;
   118→  }
   119→
   120→  @override
   121→  bool operator ==(Object other) =>
   122→      identical(this, other) ||
   123→      other is OptionType &&
   124→          runtimeType == other.runtimeType &&
   125→          innerType == other.innerType;
   126→
   127→  @override
   128→  int get hashCode => innerType.hashCode;
   129→}
   130→
   131→/// 함수 타입 (fn(i32, string) -> bool)
   132→class FunctionType extends FreeLangType {
   133→  final List<FreeLangType> paramTypes;
   134→  final FreeLangType returnType;
   135→
   136→  FunctionType({
   137→    required this.paramTypes,
   138→    required this.returnType,
   139→  });
   140→
   141→  @override
   142→  String get name {
   143→    final params = paramTypes.map((t) => t.name).join(', ');
   144→    return 'fn($params) -> ${returnType.name}';
   145→  }
   146→
   147→  @override
   148→  bool isAssignableTo(FreeLangType other) {
   149→    if (other is FunctionType) {
   150→      if (paramTypes.length != other.paramTypes.length) {
   151→        return false;
   152→      }
   153→      // 파라미터 타입과 반환 타입이 모두 일치해야 함
   154→      for (int i = 0; i < paramTypes.length; i++) {
   155→        if (!paramTypes[i].isAssignableTo(other.paramTypes[i])) {
   156→          return false;
   157→        }
   158→      }
   159→      return returnType.isAssignableTo(other.returnType);
   160→    }
   161→    return false;
   162→  }
   163→
   164→  @override
   165→  bool operator ==(Object other) =>
   166→      identical(this, other) ||
   167→      other is FunctionType &&
   168→          runtimeType == other.runtimeType &&
   169→          paramTypes == other.paramTypes &&
   170→          returnType == other.returnType;
   171→
   172→  @override
   173→  int get hashCode => Object.hash(paramTypes, returnType);
   174→}
   175→
   176→/// 타입 환경 (변수명 -> 타입 매핑)
   177→class TypeEnvironment {
   178→  final Map<String, FreeLangType> _bindings = {};
   179→  final TypeEnvironment? parent;
   180→
   181→  TypeEnvironment({this.parent});
   182→
   183→  /// 변수에 타입을 정의
   184→  void define(String name, FreeLangType type) {
   185→    _bindings[name] = type;
   186→  }
   187→
   188→  /// 변수의 타입 조회 (부모 스코프도 검색)
   189→  FreeLangType? lookup(String name) {
   190→    if (_bindings.containsKey(name)) {
   191→      return _bindings[name];
   192→    }
   193→    return parent?.lookup(name);
   194→  }
   195→
   196→  /// 자식 스코프 생성
   197→  TypeEnvironment createChild() {
   198→    return TypeEnvironment(parent: this);
   199→  }
   200→
   201→  /// 현재 스코프의 모든 바인딩 반환
   202→  Map<String, FreeLangType> getAllBindings() {
   203→    return Map.from(_bindings);
   204→  }
   205→}
   206→
   207→/// FreeLang 타입 상수 및 팩토리
   208→class FreeLangTypes {
   209→  // 기본 타입 상수
   210→  static final i32 = PrimitiveType('i32');
   211→  static final i64 = PrimitiveType('i64');
   212→  static final f32 = PrimitiveType('f32');
   213→  static final f64 = PrimitiveType('f64');
   214→  static final string = PrimitiveType('string');
   215→  static final bool_ = PrimitiveType('bool');
   216→  static final nil = PrimitiveType('nil');
   217→  static final unknown = PrimitiveType('unknown'); // 타입 추론 불가 시
   218→
   219→  /// 문자열로부터 기본 타입 생성
   220→  static FreeLangType? fromString(String typeName) {
   221→    switch (typeName.toLowerCase()) {
   222→      case 'i32':
   223→        return i32;
   224→      case 'i64':
   225→        return i64;
   226→      case 'f32':
   227→        return f32;
   228→      case 'f64':
   229→        return f64;
   230→      case 'string':
   231→        return string;
   232→      case 'bool':
   233→        return bool_;
   234→      case 'nil':
   235→        return nil;
   236→      default:
   237→        return null;
   238→    }
   239→  }
   240→
   241→  /// 타입 이름 목록
   242→  static const List<String> allTypeNames = [
   243→    'i32',
   244→    'i64',
   245→    'f32',
   246→    'f64',
   247→    'string',
   248→    'bool',
   249→    'nil',
   250→    'array',
   251→    'map',
   252→    'option',
   253→  ];
   254→}
