     1→// type_checker.dart - 정적 타입 검사
     2→// 타입 주석 검증, 조건식 타입 검증, 반환 타입 검증
     3→
     4→import 'type_system.dart';
     5→import 'type_inference.dart';
     6→import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;
     7→
     8→/// 정적 타입 검사기 (Linter.lint()과 동일한 반환 타입)
     9→class TypeChecker {
    10→  /// 코드의 모든 타입 오류를 진단 목록으로 반환
    11→  static List<Diagnostic> check(String code) {
    12→    final diagnostics = <Diagnostic>[];
    13→    final lines = code.split('\n');
    14→    final globalEnv = TypeEnvironment();
    15→
    16→    // 변수 선언 타입 검사
    17→    diagnostics.addAll(_checkVariableDeclarations(lines, globalEnv));
    18→
    19→    // if/while 조건식 타입 검사
    20→    diagnostics.addAll(_checkConditionTypes(lines, globalEnv));
    21→
    22→    // 함수 반환 타입 검사 (기본)
    23→    diagnostics.addAll(_checkReturnTypes(lines, globalEnv));
    24→
    25→    return diagnostics;
    26→  }
    27→
    28→  /// 변수 선언 및 할당 타입 검사
    29→  /// let x: i32 = "hello" -> type-mismatch 오류
    30→  /// let x: unknown_type = 10 -> unknown-type 경고
    31→  static List<Diagnostic> _checkVariableDeclarations(
    32→    List<String> lines,
    33→    TypeEnvironment env,
    34→  ) {
    35→    final diagnostics = <Diagnostic>[];
    36→
    37→    for (int i = 0; i < lines.length; i++) {
    38→      final line = lines[i];
    39→
    40→      // let x: i32 = value 패턴
    41→      final annotatedMatch = RegExp(r'let\s+(\w+)\s*:\s*(\w+)\s*=\s*(.+)')
    42→          .firstMatch(line);
    43→      if (annotatedMatch != null) {
    44→        final varName = annotatedMatch.group(1)!;
    45→        final typeStr = annotatedMatch.group(2)!;
    46→        final value = annotatedMatch.group(3)!;
    47→
    48→        // 선언된 타입 파싱
    49→        final declaredType = FreeLangTypes.fromString(typeStr);
    50→        if (declaredType == null) {
    51→          // 알 수 없는 타입
    52→          diagnostics.add(Diagnostic(
    53→            line: i,
    54→            column: annotatedMatch.start(2),
    55→            message: "Unknown type '$typeStr'",
    56→            severity: DiagnosticSeverity.warning,
    57→            code: 'unknown-type',
    58→          ));
    59→          continue;
    60→        }
    61→
    62→        // 할당값 타입 추론
    63→        final inferredType = TypeInferrer.inferLiteral(value);
    64→
    65→        // 타입 호환성 검사
    66→        if (inferredType != FreeLangTypes.unknown &&
    67→            !inferredType.isAssignableTo(declaredType)) {
    68→          diagnostics.add(Diagnostic(
    69→            line: i,
    70→            column: annotatedMatch.start(3),
    71→            message:
    72→                "Type mismatch: cannot assign ${inferredType.name} to ${declaredType.name}",
    73→            severity: DiagnosticSeverity.error,
    74→            code: 'type-mismatch',
    75→          ));
    76→        }
    77→
    78→        // 환경에 바인딩
    79→        env.define(varName, declaredType);
    80→      }
    81→
    82→      // let x = value 패턴 (타입 추론)
    83→      final inferMatch =
    84→          RegExp(r'let\s+(\w+)\s*=\s*(.+)$').firstMatch(line);
    85→      if (inferMatch != null && !line.contains(':')) {
    86→        final varName = inferMatch.group(1)!;
    87→        final value = inferMatch.group(2)!;
    88→
    89→        final inferredType = TypeInferrer.inferLiteral(value);
    90→        env.define(varName, inferredType);
    91→      }
    92→    }
    93→
    94→    return diagnostics;
    95→  }
    96→
    97→  /// if/while 조건식이 bool 타입인지 검사
    98→  /// if "string" -> invalid-condition-type 오류
    99→  static List<Diagnostic> _checkConditionTypes(
   100→    List<String> lines,
   101→    TypeEnvironment env,
   102→  ) {
   103→    final diagnostics = <Diagnostic>[];
   104→
   105→    for (int i = 0; i < lines.length; i++) {
   106→      final line = lines[i];
   107→
   108→      // if (condition) 패턴
   109→      final ifMatch = RegExp(r'if\s+\((.+?)\)').firstMatch(line);
   110→      if (ifMatch != null) {
   111→        final condition = ifMatch.group(1)!.trim();
   112→        final condType = TypeInferrer.inferExpression(condition, env);
   113→
   114→        if (condType != FreeLangTypes.unknown &&
   115→            condType != FreeLangTypes.bool_) {
   116→          diagnostics.add(Diagnostic(
   117→            line: i,
   118→            column: ifMatch.start(1),
   119→            message:
   120→                "Type error: if condition must be bool, got ${condType.name}",
   121→            severity: DiagnosticSeverity.error,
   122→            code: 'invalid-condition-type',
   123→          ));
   124→        }
   125→      }
   126→
   127→      // while (condition) 패턴
   128→      final whileMatch = RegExp(r'while\s+\((.+?)\)').firstMatch(line);
   129→      if (whileMatch != null) {
   130→        final condition = whileMatch.group(1)!.trim();
   131→        final condType = TypeInferrer.inferExpression(condition, env);
   132→
   133→        if (condType != FreeLangTypes.unknown &&
   134→            condType != FreeLangTypes.bool_) {
   135→          diagnostics.add(Diagnostic(
   136→            line: i,
   137→            column: whileMatch.start(1),
   138→            message:
